def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = my.count('C')
    my_d = n - my_c

    # Final round: defect.
    if n >= 100:
        return 'D'

    # Opening: cooperate to establish mutual reward, with one early probe.
    if n == 1:
        return 'C'
    if n == 2:
        return 'D'
    if n < 6:
        if opp[-1] == 'D':
            return 'D'
        return 'C'

    last_opp = opp[-1]
    last_my = my[-1]

    # Detect always-defect-ish opponent.
    recent10 = opp[-10:]
    rd10 = recent10.count('D')
    if rd10 >= 9:
        # Punish almost always, rare test for switches.
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Detect very cooperative opponent — exploit gently.
    if n >= 15 and rd10 == 0:
        # Occasional exploitation, but preserve cooperation.
        if n % 11 == 0:
            return 'D'
        return 'C'

    # Late game: lock in cooperation unless opponent shows recent defection.
    if n >= 90:
        recent5 = opp[-5:]
        d5 = recent5.count('D')
        if d5 >= 2:
            return 'D'
        return 'C'

    # Track long mutual-defection streaks to break cycles.
    if last_my == 'D' and last_opp == 'D':
        streak = 0
        for i in range(n - 1, -1, -1):
            if my[i] == 'D' and opp[i] == 'D':
                streak += 1
            else:
                break
        if streak >= 3:
            # Try probabilistic reconciliation.
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    # Opponent defected while we cooperated: retaliate, but with limited grudge.
    if last_opp == 'D' and last_my == 'C':
        # Count consecutive C->D exploitations.
        exploit = 0
        for i in range(n - 1, -1, -1):
            if my[i] == 'C' and opp[i] == 'D':
                exploit += 1
            else:
                break
        if exploit >= 2:
            return 'D'
        # Single isolated defection: mostly retaliate, occasional forgive.
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent cooperated after we defected: return to cooperation (TFaT).
    if last_opp == 'C' and last_my == 'D':
        return 'C'

    # Both cooperated last round: continue, with occasional probing.
    if last_opp == 'C' and last_my == 'C':
        # Probe only if opponent has been very cooperative and early-mid game.
        if n >= 20 and n < 80 and rd10 <= 1 and n % 17 == 0:
            return 'D'
        return 'C'

    # Fallback: mirror last opponent action.
    if last_opp == 'C':
        return 'C'
    return 'D'
